#!/usr/bin/env node
"use strict";
// Bundles the server judge (functions/code_judge) for the in-app code runner,
// so code is graded in the browser by exactly the same harness and rules as
// on the server. Output: web/code_runner/gg_judge.js (generated — do not edit).
//
//   node tool/build_code_runner.js          write the bundle
//   node tool/build_code_runner.js --check  exit 1 if the bundle is stale
const fs = require("node:fs");
const path = require("node:path");

const root = path.join(__dirname, "..");
const modules = ["values", "compare", "runner", "harness", "judge"];

function build() {
  const parts = [
    "/* GENERATED by tool/build_code_runner.js from functions/code_judge — do not edit. */",
    "(function (root) {",
    "  'use strict';",
    "  var defs = {}, cache = {};",
    "  function req(name) {",
    "    name = String(name).replace(/^\\.\\//, '');",
    "    if (cache[name]) return cache[name].exports;",
    "    if (!defs[name]) throw new Error('Module not available in the lab runner: ' + name);",
    "    var m = { exports: {} }; cache[name] = m; defs[name](m, m.exports, req); return m.exports;",
    "  }",
    "  var Buffer = { byteLength: function (s) { return new TextEncoder().encode(String(s)).length; } };",
  ];
  for (const name of modules) {
    const src = fs.readFileSync(path.join(root, "functions/code_judge", `${name}.js`), "utf8");
    parts.push(`  defs[${JSON.stringify(name)}] = function (module, exports, require) {`);
    parts.push(src);
    parts.push("  };");
  }
  parts.push("  root.GGJudge = req('judge');");
  parts.push("  root.GGJudge.LIMITS = req('runner').LIMITS;");
  parts.push("})(typeof self !== 'undefined' ? self : (typeof globalThis !== 'undefined' ? globalThis : this));");
  return parts.join("\n") + "\n";
}

const out = path.join(root, "web/code_runner/gg_judge.js");
if (require.main === module) {
const fresh = build();
if (process.argv.includes("--check")) {
  const current = fs.existsSync(out) ? fs.readFileSync(out, "utf8") : "";
  if (current !== fresh) {
    console.error("web/code_runner/gg_judge.js is out of date. Run: node tool/build_code_runner.js");
    process.exit(1);
  }
} else {
  fs.writeFileSync(out, fresh);
  console.log(`wrote ${path.relative(root, out)} (${fresh.length} bytes)`);
}
}
module.exports = { build, out };
